#!/usr/bin/env python3

import psutil

def check_web_server_processes():
    """Check for running web server processes"""
    web_servers = {
        'nginx': [],
        'apache': [],
        'node': []
    }

    try:
        # Iterate through all running processes
        for proc in psutil.process_iter(['pid', 'name', 'cmdline']):
            try:
                # Get process info
                pid = proc.info['pid']
                name = proc.info['name']
                cmdline = ' '.join(proc.info['cmdline']) if proc.info['cmdline'] else ''

                # Check for nginx processes
                if 'nginx' in name.lower() or 'nginx' in cmdline.lower():
                    web_servers['nginx'].append({
                        'pid': pid,
                        'name': name,
                        'cmdline': cmdline
                    })

                # Check for apache processes (httpd)
                if 'apache' in name.lower() or 'httpd' in name.lower() or 'apache' in cmdline.lower():
                    web_servers['apache'].append({
                        'pid': pid,
                        'name': name,
                        'cmdline': cmdline
                    })

                # Check for node processes
                if 'node' in name.lower() or 'node' in cmdline.lower():
                    web_servers['node'].append({
                        'pid': pid,
                        'name': name,
                        'cmdline': cmdline
                    })
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                # Process might have disappeared or we don't have access
                pass

        return web_servers
    except Exception as e:
        return {'error': str(e)}

def main():
    web_servers = check_web_server_processes()

    if 'error' in web_servers:
        print(f"Error checking processes: {web_servers['error']}")
        return

    # Print results
    print("Web Server Processes Check")
    print("=" * 30)

    # Check nginx
    if web_servers['nginx']:
        print(f"\nNginx processes ({len(web_servers['nginx'])} found):")
        for proc in web_servers['nginx']:
            print(f"  PID: {proc['pid']}, Name: {proc['name']}")
            if proc['cmdline']:
                print(f"    Command: {proc['cmdline']}")
    else:
        print("\nNo nginx processes found.")

    # Check apache
    if web_servers['apache']:
        print(f"\nApache processes ({len(web_servers['apache'])} found):")
        for proc in web_servers['apache']:
            print(f"  PID: {proc['pid']}, Name: {proc['name']}")
            if proc['cmdline']:
                print(f"    Command: {proc['cmdline']}")
    else:
        print("\nNo Apache processes found.")

    # Check node
    if web_servers['node']:
        print(f"\nNode.js processes ({len(web_servers['node'])} found):")
        for proc in web_servers['node']:
            print(f"  PID: {proc['pid']}, Name: {proc['name']}")
            if proc['cmdline']:
                print(f"    Command: {proc['cmdline']}")
    else:
        print("\nNo Node.js processes found.")

if __name__ == "__main__":
    main()

